<?php defined('BASEPATH') OR exit('No direct script access allowed'); include APPPATH . 'views/layouts/header.php'; include APPPATH . 'views/layouts/sidebar.php'; ?><div class="ami-panel"><div class="ami-panel-body"><div class="d-flex justify-content-between align-items-center flex-wrap mb-3"><h2 class="ami-section-title m-0"><?php echo html_escape($package->package_code . ' — ' . $package->title); ?></h2><?php if ($mutable): ?><span><a class="btn-ami btn-outline-ami" href="<?php echo site_url('lpmpi/spmi-instruments/package/edit/' . (int) $package->id); ?>">Edit</a> <a class="btn-ami btn-outline-ami" href="<?php echo site_url('lpmpi/spmi-instruments/question/create/' . (int) $package->id); ?>">Tambah pertanyaan</a> <?php echo form_open('lpmpi/spmi-instruments/package/delete/' . (int) $package->id, ['class' => 'd-inline', 'onsubmit' => "return confirm('Hapus paket ini? Paket hanya dapat dihapus jika belum memiliki pertanyaan.');"]); ?><button class="btn-ami btn-danger" type="submit">Hapus paket</button></form></span><?php endif; ?></div><p>Standar: <?php echo html_escape($package->standard_code . ' — ' . $package->standard_title); ?> | Versi: <?php echo html_escape($package->version_code . ' — ' . $package->version_status); ?></p><?php if (!$mutable): ?><div class="alert alert-info">Hanya-baca: versi approved, active, dan retired tidak dapat diubah.</div><?php endif; ?><p><?php echo nl2br(html_escape($package->description ?: 'Deskripsi belum diisi.')); ?></p><div class="table-responsive"><table class="table ami-table"><thead><tr><th>Urutan</th><th>Kode</th><th>Pertanyaan</th><th>Indikator</th><th>Aksi</th></tr></thead><tbody><?php if (empty($questions)): ?><tr><td colspan="5"><div class="ami-empty">Belum ada pertanyaan. Paket belum lengkap.</div></td></tr><?php else: foreach ($questions as $question): ?><tr><td><?php echo (int) $question->display_order; ?></td><td><?php echo html_escape($question->question_code); ?></td><td><?php echo html_escape($question->question_text); ?></td><td><?php echo html_escape($question->indicator_code . ' — ' . $question->indicator_title); ?></td><td><a href="<?php echo site_url('lpmpi/spmi-instruments/question/detail/' . (int) $question->id); ?>">Detail</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div><?php include APPPATH . 'views/layouts/footer.php'; ?>
